const { ExprError } = require('./errors');

/** Parse a complete token sequence into an AST. Nodes retain operator columns. */
function parse(tokens) {
  let position = 0;
  const current = () => tokens[position];
  const take = () => tokens[position++];
  const is = value => current().value === value;
  const expect = value => {
    if (!is(value)) throw new ExprError(`Expected ${value}`, current().column);
    return take();
  };
  const binary = (operator, left, right) => ({ type: 'binary', operator, left, right });

  const COMPARISONS = ['<', '<=', '>', '>=', '==', '!='];
  const FUNCTIONS = ['min', 'max', 'abs'];

  /** Chained comparison: one node holding all operands, evaluated pairwise. */
  function comparison() {
    const first = sum();
    if (!COMPARISONS.includes(current().value)) return first;
    const operands = [first];
    const operators = [];
    while (COMPARISONS.includes(current().value)) {
      operators.push(take());
      operands.push(sum());
    }
    return { type: 'comparison', operands, operators };
  }

  function sum() {
    let left = product();
    while (is('+') || is('-')) {
      const operator = take();
      left = binary(operator, left, product());
    }
    return left;
  }

  function product() {
    let left = unary();
    while (['*', '/', '//', '%'].includes(current().value)) {
      const operator = take();
      left = binary(operator, left, unary());
    }
    return left;
  }

  /** Signs are collected iteratively so long sign runs do not recurse. */
  function unary() {
    const signs = [];
    while (is('+') || is('-')) signs.push(take());
    let node = power();
    for (let i = signs.length - 1; i >= 0; i -= 1) {
      node = { type: 'unary', operator: signs[i], operand: node };
    }
    return node;
  }

  /** power := primary ('**' unary)? -- right-associative, signed exponent. */
  function power() {
    const base = primary();
    if (!is('**')) return base;
    const operator = take();
    return binary(operator, base, unary());
  }

  function primary() {
    const token = take();
    if (token.type === 'number') return { type: 'number', value: token.value };
    if (token.type === 'identifier') {
      if (!is('(')) return { type: 'variable', name: token.value, column: token.column };
      // Call errors are reported at the identifier as soon as they are knowable.
      if (!FUNCTIONS.includes(token.value)) {
        throw new ExprError('Unknown function', token.column);
      }
      take();
      if (is(')')) throw new ExprError('Wrong argument count', token.column);
      const args = [comparison()];
      while (is(',')) {
        if (token.value === 'abs') throw new ExprError('Wrong argument count', token.column);
        take();
        args.push(comparison());
      }
      expect(')');
      return { type: 'call', name: token.value, args };
    }
    if (token.value === '(') {
      const expression = comparison();
      expect(')');
      return expression;
    }
    throw new ExprError('Expected an expression', token.column);
  }

  const expression = comparison();
  if (current().type !== 'eof') throw new ExprError('Unexpected token', current().column);
  return expression;
}

module.exports = { parse };

