'use strict';

const { ExprError } = require('./errors');

/**
 * Python float floor division / modulo (CPython _float_div_mod). Exact for
 * safe integers, and correct where Math.floor(a / b) rounds wrongly
 * (e.g. 1 // 0.1 is 9). Zero results are positive zero by contract.
 */
function floorDivMod(left, right) {
  let mod = left % right;
  let div = (left - mod) / right;
  if (mod) {
    if ((right < 0) !== (mod < 0)) {
      mod += right;
      div -= 1;
    }
  } else {
    mod = 0;
  }
  let floorDiv = 0;
  if (div) {
    floorDiv = Math.floor(div);
    if (div - floorDiv > 0.5) floorDiv += 1;
  }
  return { div: floorDiv === 0 ? 0 : floorDiv, mod: mod === 0 ? 0 : mod };
}

/** Python pow for floats: 1 ** x and (-1) ** ±inf are 1, unlike JavaScript. */
function power(left, right) {
  if (left === 1) return 1;
  if (left === -1 && (right === Infinity || right === -Infinity)) return 1;
  return left ** right;
}

/** Booleans (comparison results) take part in arithmetic as 0/1. */
function apply(operator, left, right) {
  left = Number(left);
  right = Number(right);
  const value = operator.value;
  if ((value === '/' || value === '//' || value === '%') && right === 0) {
    throw new ExprError('Division by zero', operator.column);
  }
  switch (value) {
    case '+': return left + right;
    case '-': return left - right;
    case '*': return left * right;
    case '/': return left / right;
    case '**': return power(left, right);
    case '//': return floorDivMod(left, right).div;
    case '%': return floorDivMod(left, right).mod;
    case '<': return left < right;
    case '<=': return left <= right;
    case '>': return left > right;
    case '>=': return left >= right;
    case '==': return left === right;
    case '!=': return left !== right;
    default: throw new Error('Invalid AST operator');
  }
}

/** Evaluate with explicit frames, so a long left-deep binary tree is safe. */
function evaluateAst(root, variables) {
  const frames = [{ node: root, phase: 0 }];
  let result;
